import{_ as r,B as l,o,c,a8 as d,a as t,E as i,f as a}from"./chunks/framework.CNIpabDg.js";const b=JSON.parse(`{"title":"Little FS","description":"The little_fs crate is the concrete LittleFS backend that implements Xila's file-system contracts.","frontmatter":{"layout":"doc","docType":"explanation","description":"The little_fs crate is the concrete LittleFS backend that implements Xila's file-system contracts."},"headers":[],"relativePath":"explanation/architecture/libraries/little_fs.md","filePath":"explanation/architecture/libraries/little_fs.md","lastUpdated":1792488559000}`),h={name:"explanation/architecture/libraries/little_fs.md"};function u(p,e,m,f,k,y){const s=l("CodeReference"),n=l("HostReference");return o(),c("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792488559000"},[e[5]||(e[5]=d(`<h1 id="little-fs" tabindex="-1">Little FS <a class="header-anchor" href="#little-fs" aria-label="Permalink to &quot;Little FS&quot;">​</a></h1><p>The <code>little_fs</code> crate is the concrete LittleFS backend that implements Xila&#39;s file-system contracts.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><ul><li>Implements <code>file_system::FileSystemOperations</code> and related traits on top of <code>littlefs2-sys</code>.</li><li>Provides mount/format bootstrap paths used before VFS initialization.</li></ul><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>In scope: backend adaptation, attribute translation, file/directory context operations.</li><li>Out of scope: global mount namespace and path policy (owned by VFS).</li></ul><h2 id="internal-structure" tabindex="-1">Internal structure <a class="header-anchor" href="#internal-structure" aria-label="Permalink to &quot;Internal structure&quot;">​</a></h2><ul><li><code>file_system.rs</code>: <code>FileSystem</code> type, mount/format lifecycle, trait implementations.</li><li><code>callbacks.rs</code> + <code>configuration.rs</code>: glue from <code>DirectBlockDevice</code> to LittleFS C callbacks/config.</li><li><code>file.rs</code> / <code>directory.rs</code>: context-specific file and directory operations.</li><li><code>attributes.rs</code> / <code>flags.rs</code>: mapping between Xila and LittleFS representations.</li><li><code>error.rs</code>: LittleFS result-to-<code>file_system::Error</code> conversion.</li></ul><h2 id="runtime-interaction" tabindex="-1">Runtime interaction <a class="header-anchor" href="#runtime-interaction" aria-label="Permalink to &quot;Runtime interaction&quot;">​</a></h2><ol><li>Backend is created via <code>FileSystem::new(...)</code>, <code>new_format(...)</code>, or <code>get_or_format(...)</code>.</li><li>It mounts using <code>littlefs::lfs_mount</code> and seeds root internal attributes if missing.</li><li>VFS calls trait methods; crate routes calls through a mounted mutex wrapper.</li><li>On drop, it unmounts and releases leaked configuration context.</li></ol><h2 id="dependency-model" tabindex="-1">Dependency model <a class="header-anchor" href="#dependency-model" aria-label="Permalink to &quot;Dependency model&quot;">​</a></h2><ul><li>Core dependencies: <a href="/explanation/architecture/libraries/file_system.html">File system</a>, <a href="/explanation/architecture/subsystems/task.html">Task</a>, <a href="/explanation/architecture/subsystems/users.html">Users</a>, <a href="/explanation/architecture/subsystems/time.html">Time</a>, <a href="/explanation/architecture/libraries/synchronization.html">Synchronization</a>, <code>littlefs2-sys</code>.</li></ul><h2 id="failure-semantics" tabindex="-1">Failure semantics <a class="header-anchor" href="#failure-semantics" aria-label="Permalink to &quot;Failure semantics&quot;">​</a></h2><ul><li>Mount/format/operation failures are translated to <code>file_system::Error</code>.</li><li><code>get_or_format</code> retries by formatting when initial mount fails.</li><li>Context type mismatch in operation dispatch returns <code>InvalidParameter</code>.</li></ul><h2 id="extension-points" tabindex="-1">Extension points <a class="header-anchor" href="#extension-points" aria-label="Permalink to &quot;Extension points&quot;">​</a></h2><ul><li>Additional mount policies can wrap existing constructors.</li><li>New attribute/flag translations can be added without changing trait-level contracts.</li></ul><h2 id="contract-vs-implementation" tabindex="-1">Contract vs implementation <a class="header-anchor" href="#contract-vs-implementation" aria-label="Permalink to &quot;Contract vs implementation&quot;">​</a></h2><ul><li><strong>Contract</strong>: fully conforms to <code>file_system</code> trait interfaces expected by VFS.</li><li><strong>Current implementation</strong>: based on LittleFS C runtime (<code>lfs_*</code>) with <code>MutexMountWrapper&lt;CriticalSectionRawMutex, lfs_t&gt;</code>.</li></ul><h2 id="limitations-and-trade-offs" tabindex="-1">Limitations and trade-offs <a class="header-anchor" href="#limitations-and-trade-offs" aria-label="Permalink to &quot;Limitations and trade-offs&quot;">​</a></h2><ul><li>Behavior inherits LittleFS semantics and target storage constraints.</li><li>Relies on callback/config correctness; misconfigured block geometry can fail at runtime.</li></ul><h2 id="safe-mounting-and-formatting-choices" tabindex="-1">Safe mounting and formatting choices <a class="header-anchor" href="#safe-mounting-and-formatting-choices" aria-label="Permalink to &quot;Safe mounting and formatting choices&quot;">​</a></h2><p>The public constructors have distinct <strong>data-loss implications</strong>:</p><ul><li><code>FileSystem::new(device, cache_size)</code> mounts an existing filesystem and reports errors if it cannot mount.</li><li><code>FileSystem::new_format(device, cache_size)</code> <strong>formats unconditionally</strong>, then mounts. Use only for deliberately disposable or freshly initialized storage.</li><li><code>FileSystem::get_or_format(device, cache_size)</code> tries to mount, but <strong>formats whenever that first mount fails</strong>. It does not distinguish a blank disk from a corrupt disk, incompatible geometry or transient I/O failure. This is unsafe as an automatic recovery policy for a persistent user disk.</li><li><code>FileSystem::format(device, cache_size)</code> explicitly formats the underlying storage without returning a mounted filesystem.</li></ul><p>All constructors require an <code>&amp;&#39;static dyn DirectBlockDevice</code> and a cache size; they derive physical block size and count from the supplied device and build a LittleFS C configuration. Initialization populates missing root attributes. A transient lock failure during an operation may surface as <code>RessourceBusy</code>.</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Intentionally format an ephemeral in-memory block device for testing.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> device </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> file_system</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MemoryDevice</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">512</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">new_static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">512</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1024</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> filesystem </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> little_fs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">FileSystem</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">new_format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(device, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>This example is suitable for <strong>disposable test data only</strong>. For existing flash/OPFS disks, prefer <code>new</code> and handle mount failure explicitly, without automatic destruction.</p><h2 id="handle-lifetimes-metadata-and-failure-behavior" tabindex="-1">Handle lifetimes, metadata and failure behavior <a class="header-anchor" href="#handle-lifetimes-metadata-and-failure-behavior" aria-label="Permalink to &quot;Handle lifetimes, metadata and failure behavior&quot;">​</a></h2><p>The backend wraps the mounted <code>littlefs::lfs_t</code> in <code>MutexMountWrapper&lt;CriticalSectionRawMutex, _&gt;</code>. Open file/directory contexts use shared <code>Arc&lt;Mutex&lt;...&gt;&gt;</code> state rather than duplicating raw LittleFS C caches. <code>operation_with_context</code> verifies the stored type and uses <code>try_lock</code>; a mismatch yields <code>InvalidParameter</code>, and contention yields <code>RessourceBusy</code>.</p><p><code>writable_attributes()</code> advertises the specific <code>InternalAttributes::PERSISTED_ATTRIBUTE_FLAGS</code>. This is important: LittleFS cannot necessarily store every VFS-provided timestamp or metadata field. The backend translates file/directory operations through <code>lfs_*</code> and maps LittleFS error codes to <code>file_system::Error</code>.</p><p>A target storage driver must provide correct block geometry, read/program/erase semantics and durability on flush. Cache size and driver alignment need to fit the underlying device; using a correctly mounted VFS cannot compensate for a broken block callback.</p><h3 id="source-and-api-references" tabindex="-1">Source and API references <a class="header-anchor" href="#source-and-api-references" aria-label="Permalink to &quot;Source and API references&quot;">​</a></h3>`,31)),t("ul",null,[t("li",null,[i(s,{path:"libraries/little_fs/src/file_system.rs"}),e[0]||(e[0]=a(" — constructors, mount wrapper and attributes.",-1))]),t("li",null,[i(s,{path:"libraries/little_fs/src/configuration.rs"}),e[1]||(e[1]=a(" — LittleFS geometry and callbacks.",-1))]),t("li",null,[i(s,{path:"libraries/little_fs/src/attributes.rs"}),e[2]||(e[2]=a(" — persisted metadata flags.",-1))]),t("li",null,[i(n,{crate:"little_fs",kind:"struct",symbol:"FileSystem"}),e[3]||(e[3]=a(" — concrete backend.",-1))])]),e[6]||(e[6]=t("h2",{id:"references",tabindex:"-1"},[a("References "),t("a",{class:"header-anchor",href:"#references","aria-label":'Permalink to "References"'},"​")],-1)),t("ul",null,[t("li",null,[i(n,{crate:"little_fs"})]),t("li",null,[i(s,{path:"libraries/little_fs"})]),e[4]||(e[4]=t("li",null,[t("a",{href:"/explanation/architecture/subsystems/virtual_file_system.html"},"Virtual file system")],-1))])])}const F=r(h,[["render",u]]);export{b as __pageData,F as default};
